import React, { useState } from 'react';
import Header from './components/Header';
import MainMenu from './components/MainMenu';
import ColorGuide from './components/ColorGuide';
import TextColorGuide from './components/TextColorGuide';
import PhraseGuide from './components/PhraseGuide';
import PngGuide from './components/PngGuide';
import TemplateGuide from './components/TemplateGuide';
import FullGuide from './components/FullGuide';

export type MenuItem = 
  | 'main'
  | 'color'
  | 'text-color'
  | 'phrase'
  | 'png'
  | 'template'
  | 'full-guide';

function App() {
  const [currentMenu, setCurrentMenu] = useState<MenuItem>('main');

  const renderContent = () => {
    switch (currentMenu) {
      case 'color':
        return <ColorGuide onBack={() => setCurrentMenu('main')} />;
      case 'text-color':
        return <TextColorGuide onBack={() => setCurrentMenu('main')} />;
      case 'phrase':
        return <PhraseGuide onBack={() => setCurrentMenu('main')} />;
      case 'png':
        return <PngGuide onBack={() => setCurrentMenu('main')} />;
      case 'template':
        return <TemplateGuide onBack={() => setCurrentMenu('main')} />;
      case 'full-guide':
        return <FullGuide onBack={() => setCurrentMenu('main')} />;
      default:
        return <MainMenu onMenuSelect={setCurrentMenu} />;
    }
  };

  return (
    <div className="App">
      <Header />
      <div className="container">
        {renderContent()}
      </div>
    </div>
  );
}

export default App;
